    const [report, setReport] = useState(null), [reportFrom, setReportFrom] = useState(today.slice(0, 8) + '01'), [reportTo, setReportTo] = useState(today), [reportPeriod, setReportPeriod] = useState('month');
    const [sunatSettings, setSunatSettings] = useState(null), [sunatMode, setSunatMode] = useState('internal'), [sunatConnection, setSunatConnection] = useState(null), [sunatBusy, setSunatBusy] = useState(false);
    const activeCash = cashSessions.find((session) => String(session.warehouse_id) === String(warehouseId));
    const salePriceCents = (presentation) => salePriceList === 'wholesale' && presentation.wholesale_price_cents != null ? Number(presentation.wholesale_price_cents) : Number(presentation.price_cents);
    const saleTotalCents = saleCart.reduce((sum, line) => sum + Math.max(0, Math.round((line.unit_price_cents ?? salePriceCents(line.presentation)) * Number(line.quantity)) - Number(line.discount_cents || 0)), 0);
    const salePaidCents = salePayments.reduce((sum, payment) => sum + Math.round(Number(payment.amount || 0) * 100), 0);
