    function shareTicketWhatsApp(sale) {
        const lines = (sale.lines || []).map((line) => `${line.product_name_snapshot} · ${line.quantity} × S/ ${(line.unit_price_cents / 100).toFixed(2)} = S/ ${(line.line_total_cents / 100).toFixed(2)}`);
        const message = ['U.LIONS IMPORT · Ticket de venta', sale.sale_number, ...lines, `Total: S/ ${(sale.total_cents / 100).toFixed(2)}`, 'Gracias por su compra.'].join('\n');
        window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank', 'noopener,noreferrer');
    }
    async function submitSale(event) {
        event.preventDefault(); setError('');
        const payments = salePayments.map((payment) => ({ ...payment, amount_cents: Math.round(Number(payment.amount || 0) * 100) })).filter((payment) => payment.amount_cents > 0).map(({ method, amount_cents, reference }) => ({ method, amount_cents, reference: reference || null }));
        if (!activeCash || !saleCart.length) return;
        if (salePaidCents > saleTotalCents) { setError('El importe pagado no puede superar el total de la venta.'); return; }
        if (salePaidCents < saleTotalCents && !saleCustomerId) { setError('Selecciona un cliente para registrar el saldo como crédito.'); return; }
        try { const { data } = await axios.post('/api/v1/sales', { operation_key: saleOperationKey, cash_session_id: activeCash.id, warehouse_location_id: saleLocationId || warehouses.find((w) => String(w.id) === String(activeCash.warehouse_id))?.location_id, customer_id: saleCustomerId || null, due_date: saleDueDate || null, price_list: salePriceList, lines: saleCart.map((line) => ({ product_id: line.product.id, presentation_id: line.presentation.id, quantity: line.quantity, discount_cents: Number(line.discount_cents || 0), ...(line.unit_price_cents != null ? { unit_price_cents: line.unit_price_cents } : {}) })), payments }); setModal({ type: 'ticket', sale: data.data }); setSaleCart([]); setSaleCustomerId(''); setSaleSearch(''); setSaleDueDate(''); setSalePayments([{ method: 'cash', amount: '0.00', reference: '', automatic: true }]); setSaleOperationKey(crypto.randomUUID()); await refresh(); notify('Venta registrada y stock actualizado.'); }
        catch (e) { setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || 'No se pudo registrar la venta.'); }
    }
    function addSaleProduct(product, presentationId = null, quantity = 1) {
        const presentation = product?.presentations.find((item) => String(item.id) === String(presentationId)) || product?.presentations.find((item) => item.is_base) || product?.presentations[0];
        if (!product || !presentation) return;
        setSaleCart((cart) => {
            const key = `${product.id}:${presentation.id}`;
            const existing = cart.find((line) => line.key === key);
            return existing ? cart.map((line) => line.key === key ? { ...line, quantity: Number(line.quantity) + Number(quantity) } : line) : [...cart, { key, product, presentation, quantity: Number(quantity) }];
        });
        setSaleSearch('');
    }
    function printCustomerStatement(account) {
        const popup = window.open('', '_blank');
        if (!popup) { notify('Permite ventanas emergentes para imprimir el estado de cuenta.'); return; }
        const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
        const money = (cents) => 'S/ ' + (Number(cents || 0) / 100).toFixed(2);
        const salesRows = account.sales.map((sale) => '<tr><td>' + escape(sale.sale_number) + '</td><td>' + escape(new Date(sale.sold_at).toLocaleDateString('es-PE')) + '</td><td>' + escape(sale.due_date || '—') + '</td><td>' + escape(money(sale.total_cents)) + '</td><td>' + escape(money(sale.paid_cents)) + '</td><td>' + escape(money(sale.balance_cents)) + '</td><td>' + escape((sale.payments || []).map((payment) => money(payment.amount_cents) + ' · ' + new Date(payment.created_at).toLocaleDateString('es-PE')).join(' / ') || '—') + '</td></tr>').join('');
        const advanceRows = account.advance_history.map((entry) => '<tr><td>' + escape(new Date(entry.created_at).toLocaleString('es-PE')) + '</td><td>' + escape(entry.kind === 'advance' ? 'Adelanto recibido' : 'Aplicación a ' + (entry.sale?.sale_number || 'venta')) + '</td><td>' + escape(entry.reference || '—') + '</td><td>' + escape(money(entry.amount_cents)) + '</td></tr>').join('');
        popup.document.write('<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Estado de cuenta · ' + escape(account.customer.name) + '</title><style>body{font:14px Arial,sans-serif;color:#17261f;margin:36px}header{display:flex;align-items:center;gap:18px;border-bottom:2px solid #a17a2f;padding-bottom:16px}img{width:72px;height:72px;object-fit:cover;border-radius:10px}h1{font-size:24px;margin:4px 0}p{margin:5px 0;color:#526158}.summary{display:flex;gap:20px;margin:22px 0}.summary div{padding:14px;border:1px solid #ddd;border-radius:8px;min-width:170px}h2{font-size:17px;margin:22px 0 8px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:8px;border-bottom:1px solid #ddd}th{background:#f6f2e8}.right{text-align:right}.foot{margin-top:30px;color:#627067;font-size:11px}@media print{body{margin:15mm}}</style></head><body><header><img src="' + escape(location.origin + '/images/lions-logo.jpeg') + '"><div><b>U.LIONS IMPORT · ERP</b><h1>Estado de cuenta del cliente</h1><p>Generado: ' + escape(new Date().toLocaleString('es-PE')) + '</p></div></header><h2>' + escape(account.customer.name) + '</h2><p>Identificación (' + escape(({ dni: 'DNI', ruc: 'RUC', other: 'Otro' }[account.customer.tax_id_type] || 'ID')) + '): ' + escape(account.customer.tax_id || '—') + ' · Teléfono: ' + escape(account.customer.phone || '—') + '</p><p>Dirección: ' + escape(account.customer.address || '—') + '</p><section class="summary"><div><b>Por cobrar</b><br>' + escape(money(account.outstanding_cents)) + '</div><div><b>Saldo a favor</b><br>' + escape(money(account.advance_balance_cents)) + '</div><div><b>Límite de crédito</b><br>' + escape(money(account.customer.credit_limit_cents)) + '</div></section><h2>Ventas y cobranzas</h2><table><thead><tr><th>Venta</th><th>Fecha</th><th>Vencimiento</th><th>Total</th><th>Pagado</th><th>Saldo</th><th>Abonos</th></tr></thead><tbody>' + (salesRows || '<tr><td colspan="7">Sin ventas.</td></tr>') + '</tbody></table><h2>Adelantos y saldos a favor</h2><table><thead><tr><th>Fecha</th><th>Movimiento</th><th>Referencia</th><th>Importe</th></tr></thead><tbody>' + (advanceRows || '<tr><td colspan="4">Sin movimientos de adelanto.</td></tr>') + '</tbody></table><p class="foot">Documento interno de consulta. No es comprobante tributario ni constancia oficial de pago.</p><script>window.addEventListener("load",()=>window.print())</script></body></html>');
        popup.document.close();
    }
    function printCustomerReceipt(customer, sale, payment) {
        const popup = window.open('', '_blank');
        if (!popup) { notify('Permite ventanas emergentes para imprimir la constancia.'); return; }
        const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]));
        const methods = { cash: 'Efectivo', card: 'Tarjeta', transfer: 'Transferencia', other: 'Otro', advance: 'Adelanto' };
        popup.document.write('<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Constancia de cobranza</title><style>body{font:15px Arial,sans-serif;color:#17261f;margin:36px;max-width:720px}header{display:flex;align-items:center;gap:16px;border-bottom:2px solid #a17a2f;padding-bottom:14px}img{width:70px;height:70px;object-fit:cover;border-radius:10px}h1{font-size:22px;margin:22px 0 8px}p{line-height:1.6}.amount{font-size:24px;font-weight:bold;color:#9a742d;padding:20px 0}.notice{margin-top:35px;padding-top:12px;border-top:1px solid #ddd;color:#68756d;font-size:11px}@media print{body{margin:15mm}}</style></head><body><header><img src="' + escape(location.origin + '/images/lions-logo.jpeg') + '"><div><b>U.LIONS IMPORT · ERP</b><div>Constancia interna de cobranza</div></div></header><h1>Abono recibido</h1><p><b>Cliente:</b> ' + escape(customer.name) + '<br><b>Venta:</b> ' + escape(sale.sale_number) + '<br><b>Fecha:</b> ' + escape(new Date(payment.created_at).toLocaleString('es-PE')) + '<br><b>Medio:</b> ' + escape(methods[payment.method] || payment.method) + '<br><b>Referencia:</b> ' + escape(payment.reference || '—') + '</p><div class="amount">S/ ' + (Number(payment.amount_cents || 0) / 100).toFixed(2) + '</div><p>Saldo de la venta después del abono: S/ ' + (Math.max(0, Number(sale.total_cents) - Number(sale.paid_cents)) / 100).toFixed(2) + '</p><div class="notice">Constancia interna de control de pago. No es comprobante tributario ni documento oficial emitido por SUNAT.</div><script>window.addEventListener("load",()=>window.print())</script></body></html>');
        popup.document.close();
    }
    async function openCustomerAccount(customer) {
        setError('');
        try { const { data } = await axios.get('/api/v1/customers/' + customer.id + '/account'); setCustomerAccount(data.data); }
        catch { setError('No se pudo cargar el estado de cuenta.'); }
    }
    async function submitCustomer(event) {
        event.preventDefault(); setError(''); const form = new FormData(event.currentTarget);
        const data = Object.fromEntries(form); data.credit_limit_cents = Math.round(Number(data.credit_limit || 0) * 100); delete data.credit_limit;
        try { await axios.post('/api/v1/customers', data); setModal(null); await refresh(); notify('Cliente registrado.'); }
        catch (e) { setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || 'No se pudo guardar el cliente.'); }
    }
    async function submitCollection(event) {
        event.preventDefault(); setError(''); const form = new FormData(event.currentTarget); const sale = modal.sale;
        try {
            await axios.post('/api/v1/sales/' + sale.id + '/payments', { operation_key: modal.operationKey, cash_session_id: modal.cashSession.id, method: form.get('method'), amount_cents: Math.round(Number(form.get('amount') || 0) * 100), reference: form.get('reference') || null });
            setModal(null); await refresh(); const customer = customers.find((item) => item.id === sale.customer_id); if (customer) await openCustomerAccount(customer); notify('Cobranza registrada.');
        } catch (e) { setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || 'No se pudo registrar el pago.'); }
    }
    async function submitSaleReturn(event) {
        event.preventDefault(); setError(''); const form = new FormData(event.currentTarget);
        const reason = form.get('reason'); const refundMethod = form.get('refund_method') || null;
        const payload = { operation_key: modal.operationKey, reason, refund_method: refundMethod, cash_session_id: activeCash?.id || null };
        try {
            const endpoint = modal.cancel ? 'cancel' : 'returns';
            if (!modal.cancel) payload.lines = [{ sale_line_id: form.get('sale_line_id'), quantity: form.get('quantity') }];
            await axios.post(`/api/v1/sales/${modal.sale.id}/${endpoint}`, payload);
            setModal(null); await refresh(); notify(modal.cancel ? 'Venta anulada, stock restituido y saldo ajustado.' : 'Devolución registrada y stock restituido.');
        } catch (e) { setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || 'No se pudo registrar la devolución.'); }
    }
    async function submitAdvance(event) {
        event.preventDefault(); setError(''); const form = new FormData(event.currentTarget);
        try { await axios.post(`/api/v1/customers/${modal.customer.id}/advances`, { operation_key: modal.operationKey, cash_session_id: activeCash.id, method: form.get('method'), amount_cents: Math.round(Number(form.get('amount') || 0) * 100), reference: form.get('reference') || null }); setModal(null); await refresh(); await openCustomerAccount(modal.customer); notify('Adelanto registrado como saldo a favor.'); }
        catch (e) { setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || 'No se pudo registrar el adelanto.'); }
    }
