    async function issueSunatCpe(sale, documentType) {
        setError(''); setSunatBusy(true);
        try {
            const { data } = await axios.post('/api/v1/sales/' + sale.id + '/sunat-document', { document_type: documentType });
            const issued = data.data;
            setModal((current) => current?.type === 'saleDetail' && current.sale.id === sale.id
                ? { ...current, sale: { ...current.sale, documents: [...(current.sale.documents || []), issued] } }
                : current);
            await refresh();
            notify((documentType === 'invoice' ? 'Factura' : 'Boleta') + ' enviada a SUNAT Beta: ' + (issued.status === 'accepted' ? 'aceptada' : issued.status === 'rejected' ? 'rechazada' : issued.status) + '.');
        } catch (e) {
            setError(Object.values(e.response?.data?.errors || {}).flat().join(' ') || e.response?.data?.message || 'No se pudo enviar el comprobante a SUNAT Beta.');
        } finally { setSunatBusy(false); }
    }
