                {modal.type === 'customer' && <div className="form-grid"><div className="field full"><label>Nombre / razón social</label><input name="name" required maxLength="180" /></div><div className="field"><label>Tipo de documento</label><select name="tax_id_type" defaultValue=""><option value="">Sin documento</option><option value="dni">DNI</option><option value="ruc">RUC</option><option value="other">Otro</option></select></div><div className="field"><label>Número de documento</label><input name="tax_id" maxLength="20" inputMode="numeric" /></div><div className="field"><label>Correo</label><input name="email" type="email" maxLength="255" /></div><div className="field"><label>Teléfono</label><input name="phone" maxLength="40" /></div><div className="field"><label>Límite de crédito (S/)</label><input name="credit_limit" type="number" min="0" step="0.01" defaultValue="0" required /></div><div className="field full"><label>Dirección</label><input name="address" maxLength="2000" /></div><div className="field full"><small>Se valida el formato: DNI de 8 dígitos y RUC de 11 dígitos. No se consulta el padrón de SUNAT/RENIEC.</small></div></div>}
