                {modal.type === 'advanceApply' && <div className="form-grid"><div className="field full"><div className="alert">Saldo a favor disponible: S/ {(modal.available_cents / 100).toFixed(2)} · saldo de la venta: S/ {((modal.sale.total_cents - modal.sale.paid_cents) / 100).toFixed(2)}</div></div><div className="field full"><label>Importe a aplicar (S/)</label><input name="amount" type="number" min="0.01" max={(Math.min(modal.available_cents, modal.sale.total_cents - modal.sale.paid_cents) / 100).toFixed(2)} step="0.01" defaultValue={(Math.min(modal.available_cents, modal.sale.total_cents - modal.sale.paid_cents) / 100).toFixed(2)} required /></div></div>}
                {modal.type === 'saleReturn' && <div className="form-grid">{!modal.cancel && <><div className="field full"><label>Producto vendido</label><select name="sale_line_id" required>{modal.sale.lines.filter((line) => Number(line.quantity) > Number(line.returned_quantity || 0)).map((line) => <option key={line.id} value={line.id}>{line.product_name_snapshot} · vendido {line.quantity} · devuelto {line.returned_quantity || 0}</option>)}</select></div><div className="field"><label>Cantidad a devolver</label><input name="quantity" type="number" min="0.000001" step="0.000001" required /></div></>}<div className="field full"><label>Motivo</label><input name="reason" required minLength="3" maxLength="500" /></div><div className="field"><label>Reembolso, si ya fue cobrado</label><select name="refund_method"><option value="">Aplicar primero al saldo pendiente</option><option value="cash">Efectivo desde caja abierta</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option><option value="other">Otro</option></select></div><div className="field full"><small>Solo gerencia o administración. El stock vuelve a la ubicación original; el monto reduce la deuda pendiente antes de reembolsar pagos.</small></div></div>}
                {modal.type === 'collection' && <div className="form-grid"><div className="field full"><div className="alert">Saldo pendiente: S/ {((modal.sale.total_cents - modal.sale.paid_cents) / 100).toFixed(2)} · caja {modal.cashSession?.warehouse?.name || ''}</div></div><div className="field"><label>Importe recibido (S/)</label><input name="amount" type="number" min="0.01" max={((modal.sale.total_cents - modal.sale.paid_cents) / 100).toFixed(2)} step="0.01" required /></div><div className="field"><label>Medio de pago</label><select name="method"><option value="cash">Efectivo</option><option value="card">Tarjeta</option><option value="transfer">Transferencia</option><option value="other">Otro</option></select></div><div className="field full"><label>Referencia (opcional)</label><input name="reference" maxLength="120" /></div></div>}
                {modal.type === 'deliveryOrder' && <div className="form-grid"><div className="field full"><label>Ubicación de reserva y entrega</label><select name="warehouse_location_id" defaultValue={warehouses.find((w) => String(w.id) === String(warehouseId))?.location_id} required>{warehouses.find((w) => String(w.id) === String(warehouseId))?.locations?.map((location) => <option key={location.id} value={location.id}>{location.code} · {location.name}</option>)}</select></div><div className="field"><label>Cliente</label><select name="customer_id" required>{customers.map((customer) => <option key={customer.id} value={customer.id}>{customer.name}</option>)}</select></div><div className="field"><label>Canal de ingreso</label><select name="source"><option value="whatsapp">WhatsApp</option><option value="in_person">Presencial</option><option value="phone">Teléfono</option><option value="other">Otro</option></select></div>{orderDraftLines.map((line, index) => { const product = products.find((item) => String(item.id) === String(line.product_id)); return <div className="field full order-draft-line" key={index}><label>Producto {index + 1}</label><div className="toolbar"><select value={line.product_id} required onChange={(e) => { const selected = products.find((item) => String(item.id) === e.target.value); setOrderDraftLines((rows) => rows.map((row, i) => i === index ? { ...row, product_id: e.target.value, presentation_id: String(selected?.presentations?.find((v) => v.is_active && v.is_base)?.id || selected?.presentations?.find((v) => v.is_active)?.id || '') } : row)); }}><option value="">Selecciona producto</option>{products.filter((item) => item.is_active).map((item) => <option key={item.id} value={item.id}>{item.name} · {item.sku}</option>)}</select><select value={line.presentation_id} required onChange={(e) => setOrderDraftLines((rows) => rows.map((row, i) => i === index ? { ...row, presentation_id: e.target.value } : row))}><option value="">Presentación</option>{product?.presentations.filter((v) => v.is_active).map((v) => <option key={v.id} value={v.id}>{v.name} · {v.price_cents / 100} S/</option>)}</select><input aria-label="Cantidad" type="number" min="0.000001" step="0.000001" value={line.quantity} required onChange={(e) => setOrderDraftLines((rows) => rows.map((row, i) => i === index ? { ...row, quantity: e.target.value } : row))} />{orderDraftLines.length > 1 && <button type="button" className="icon-btn" onClick={() => setOrderDraftLines((rows) => rows.filter((_, i) => i !== index))}>Quitar</button>}</div></div>})}<div className="field full"><button type="button" className="icon-btn" onClick={() => setOrderDraftLines((rows) => [...rows, { product_id: '', presentation_id: '', quantity: '1' }])}>＋ Añadir producto</button></div><div className="field full"><label>Dirección de entrega</label><input name="delivery_address" maxLength="2000" placeholder="Dirección o punto de recojo" /></div><div className="field"><label>Contacto de entrega</label><input name="delivery_contact" maxLength="180" /></div><div className="field"><label>Responsable de despacho</label><input name="dispatch_responsible" maxLength="180" placeholder="Persona asignada" /></div><div className="field full"><label>Notas</label><input name="notes" maxLength="2000" /></div><div className="field full"><small>Al confirmar, el sistema reserva el stock de todas las líneas. El usuario que registra la entrega queda auditado.</small></div></div>}
